mapper.insert:
/* userDAO.insertUserInfo */
INSERT INTO member.user_info (user_id, user_pw, name, email, phone, birth_dt, status, reg_dt, mod_dt, use_yn)
VALUES (#{userId}, #{userPw}, #{name}, #{email}, #{phone}, #{birthDt}, 'A', NOW(), NULL, 'Y')

mapper.select:
/* userDAO.selectUserInfo */ SELECT seq, user_id, user_pw, name, email, phone, birth_dt, status, reg_dt, mod_dt, use_yn FROM member.user_info WHERE 1 = 1
AND seq = #{seq}
AND user_id = #{id}
